typedef int value_t;
struct meter { value_t raw_count; };
union payload { value_t amount; };
enum stage { ORDER_PENDING = 1 };
value_t transform(value_t input);

sources.src/main.c:
#include "api.h"
int main(void) {
    struct meter reading = { .raw_count = 2 };
    union payload item = { .amount = 3 };
    enum stage status = ORDER_PENDING;
    int meter = 7;
    int payload = 8;
    int stage = 9;
    /* struct meter, union payload and enum stage */
    const char *label = "struct meter union payload enum stage";
    return transform(meter + payload + stage) + ((struct meter *)&reading)->raw_count
        + ((union payload *)&item)->amount + (int)((enum stage)status)
        + sizeof(struct meter) + sizeof(union payload) + sizeof(enum stage) + label[0];
}

